package dev.navifold.player;
import org.json.*;import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public class MediaSortTest {
 JSONObject item(String title)throws Exception{return new JSONObject().put("title",title);}
 @Test public void languagePriorityAndArticles()throws Exception{List<JSONObject> list=new ArrayList<>(Arrays.asList(item("The Beatles"),item("가나다"),item("42"),item("!"),item("ABBA")));list.sort(MediaSort.comparator("alphabeticalByName",true));assertEquals("42",list.get(0).getString("title"));assertEquals("가나다",list.get(1).getString("title"));assertEquals("ABBA",list.get(2).getString("title"));assertEquals("The Beatles",list.get(3).getString("title"));assertEquals("Beatles",MediaSort.name("The Beatles",true));assertEquals("The Beatles",MediaSort.name("The Beatles",false));}
 @Test public void missingDatesAlwaysLast()throws Exception{JSONObject missing=item("a"),old=item("b").put("year",1990),recent=item("c").put("year",2026);for(String mode:new String[]{"byYear","byYearAscending"}){List<JSONObject> list=new ArrayList<>(Arrays.asList(missing,old,recent));list.sort(MediaSort.comparator(mode,true));assertSame(missing,list.get(2));assertSame(mode.equals("byYear")?recent:old,list.get(0));}}
 @Test public void discBeforeTrackAndUnknownTrackLast()throws Exception{JSONObject disc2=item("a").put("discNumber",2).put("track",1),disc1=item("z").put("discNumber",1).put("track",9),unknown=item("b").put("discNumber",2);List<JSONObject> list=new ArrayList<>(Arrays.asList(unknown,disc2,disc1));list.sort(MediaSort.comparator("track",true));assertSame(disc1,list.get(0));assertSame(disc2,list.get(1));assertSame(unknown,list.get(2));}
 @Test public void newestAliasesAndNull()throws Exception{JSONObject older=item("a").put("created_at","2020-01-01"),newer=item("b").put("created","2026-01-01"),missing=item("c").put("created",JSONObject.NULL);List<JSONObject> list=new ArrayList<>(Arrays.asList(missing,older,newer));list.sort(MediaSort.comparator("newest",true));assertSame(newer,list.get(0));assertSame(missing,list.get(2));}
 @Test public void mostPlayedAndReleaseObject()throws Exception{assertTrue(MediaSort.comparator("frequent",true).compare(item("z").put("playCount",12),item("a").put("playCount",2))<0);assertEquals("2020-03-01",MediaSort.date(item("a").put("releaseDate",new JSONObject().put("year",2020).put("month",3)),false));}
}
